<?php
namespace App\Models;use Illuminate\Database\Eloquent\{Model,SoftDeletes};class TrainingTopic extends Model{use SoftDeletes;protected $fillable=['company_id','code','name','description','training_type','general_objective','specific_objectives','contents','suggested_duration_minutes','suggested_modality','requires_evaluation_default','evaluation_method','default_passing_score','default_maximum_attempts','requires_reinforcement_on_failure','issues_internal_certificate','is_regulated','regulation_reference','is_active','created_by','updated_by'];protected $casts=['requires_evaluation_default'=>'boolean','requires_reinforcement_on_failure'=>'boolean','issues_internal_certificate'=>'boolean','default_passing_score'=>'decimal:2','is_regulated'=>'boolean','is_active'=>'boolean'];public function scopeAvailableTo($q,int$id){return$q->where(fn($x)=>$x->whereNull('company_id')->orWhere('company_id',$id));}public function items(){return$this->hasMany(TrainingProgramItem::class);}public function questions(){return$this->hasMany(TrainingQuestion::class);}public function requirements(){return$this->hasMany(TrainingRequirement::class);}}
